  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  const c_ben_0_2 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "25.00", "date": "2026-03-28"}));
  const c_ada_1 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "3.33", "date": "2026-03-28"}));
  expect(await ui.editPerson(pg_wes, p_ada, {"grade": "C"})).toBe(true);
  expect(await ui.addPatron(pg_wes, p_ada, "Cam")).toBe(false);
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "20.00", "date": "2026-03-15"})).toBeNull();
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_ada_1, "Ben")).toBe(true);
  expect(await ui.bulkOpen(pg_wes, [c_ada_0, c_ada_1])).toEqual({ opened: 2, refused: 0 });
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
