import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened: the sheet's next (1, 2, ...), or within its period (<period>-<n>, X-<n> in none); none for a draft. */
  number: string | null;
  /** The due fixed when the claim was settled; none while live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The signed-in user who opened the claim; none when it was never opened. They cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals `statedDue` (none: n/a). */
  stated: boolean;
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; none for any other claim. */
  corrects: string | null };

/** Whether a claim counts toward claimed, due and every total: only OPEN, PENDING and SETTLED claims do, and a held
 *  person's (`held`: the ids of the people on hold) OPEN and PENDING claims do not. */
export function counts(claim: { status: ClaimStatus; personId: number }, held: ReadonlySet<number>): boolean {
  if (claim.status === 'OPEN' || claim.status === 'PENDING') return !held.has(claim.personId);
  return claim.status === 'SETTLED';
}

/** The key every feature reads the sheet's claims under. */
export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** Which claim's editor is open (search param `editClaim`); none means each claim form adds. */
export function useEditingClaim() {
  return useSearchParam('editClaim', asNumber);
  return whole;
}

/** The late charge's terms as of the sheet's today: its terms in days and its late percent (in hundredths); and
 *  the sheet's policy date (its today when blank) with the date of each numbered claim, which decide how a claim's
 *  live figures round. */
export type Late = { today: string; termsDays: number; pctHundredths: bigint; policyDate: string;
  dateOfNumber: ReadonlyMap<string, string> };

/** Whether the claim's live figures round half up: it (or, for a correction, the claim it corrects) is dated before
 *  the sheet's policy date; on or after it they round half to even. Half to even until the sheet's today is known. */
export function roundsHalfUp(late: Late | undefined, claim: { date: string; corrects?: string | null }): boolean {
  if (late === undefined) return false;
  const on = (claim.corrects != null ? late.dateOfNumber.get(claim.corrects) : undefined) ?? claim.date;
  return on < late.policyDate;
}

/** A date (yyyy-mm-dd) plus a number of days, as yyyy-mm-dd. */
export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** The days from one date (yyyy-mm-dd) to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** Whether a claim is a correction: its amount is below 0.00. A correction has no floor and no late charge. */
export function isCorrection(claim: { amount: string }): boolean {
  return claim.amount.trim().startsWith('-') && toHundredths(claim.amount.trim().slice(1)) > 0n;
}

/** Whether a claim is still live and payable: OPEN, or PENDING a steward's approval of its settle. */
export function isOpen(claim: { status: string }): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether the person's last statement binds the claim to its `statedDue`: it was stated, and is not PENDING (a PENDING
 *  claim shows and totals its live figure; rejected back to OPEN, it is bound again). */
export function isBound(claim: { stated: boolean; status?: string }): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** A claim's late charge in cents on its figure: for an OPEN (or PENDING) claim past its due-by (its date plus the terms), the
 *  late percent of the figure for every full 30 days it is overdue, rounded half to even; otherwise (or for a correction) 0. */
export function lateCents(late: Late | undefined, claim: { amount: string; date: string; status: string; corrects?: string | null },
  figureCents: bigint): bigint {
  if (late === undefined || !isOpen(claim) || isCorrection(claim)) return 0n;
  const overdue = daysBetween(addDays(claim.date, late.termsDays), late.today);
  const periods = overdue > 0 ? BigInt(Math.floor(overdue / 30)) : 0n;
  return periods === 0n ? 0n : dueCents(figureCents * periods, late.pctHundredths, roundsHalfUp(late, claim));
}

/** A claim's due figure in cents: fixed when it was settled; while a statement binds it, the figure it was bound to;
 *  otherwise (or while it is PENDING) its amount times its person's grade's rate
 *  in force on the claim's date, rounded half to even (half up when `halfUp`), and at least the sheet's floor (in cents) unless it is a correction. Null when there is
 *  no figure (no rate of the grade then). */
export function claimFigureCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; status?: string; settledDue: string | null; stated: boolean; statedDue: string | null },
  floorCents: bigint, halfUp = false): bigint | null {
  if (claim.settledDue != null) return toHundredths(claim.settledDue);
  if (isBound(claim)) return claim.statedDue == null ? null : toHundredths(claim.statedDue);
  const found = grade === undefined ? undefined : rateOn(rates, grade, claim.date);
  if (found === undefined) return null;

/** The terms a sheet starts with, until they are set: the days after its date a claim is due by. */
export const TERMS_DEFAULT = '14';

/** The sheet's terms in days: a claim is due by its date plus these (14 until they are set). */
export function useTermsDays(sheetId: string): number {
  const value = useSettings(sheetId).data?.find((s) => s.key === 'terms')?.value ?? TERMS_DEFAULT;
  return Number(value);
}

/** The late percent a sheet starts with, until it is set. */
export const LATE_PCT_DEFAULT = '0.00';

/** The sheet's late charge as of its today: its terms and its late percent (0.00 until it is set); with its
 *  policy date (its today while blank) and the numbered claims' dates, which decide how each claim rounds. Undefined
 *  until the sheet's today is known. */
export function useLate(sheetId: string): Late | undefined {
  const settings = useSettings(sheetId).data;
  const pct = settings?.find((s) => s.key === 'late-pct')?.value ?? LATE_PCT_DEFAULT;
  const policy = settings?.find((s) => s.key === 'policy-date')?.value ?? '';
  const termsDays = useTermsDays(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId).data;
  const dateOfNumber = new Map<string, string>();
  for (const c of claims ?? []) if (c.number != null) dateOfNumber.set(c.number, c.date);
  return today === undefined ? undefined
    : { today, termsDays, pctHundredths: toHundredths(pct), policyDate: policy === '' ? today : policy, dateOfNumber };
}
import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useFloorCents, useLate, useTermsDays } from '../access/useAccess';
import { counts, useClaims } from '../claims/useClaims';
import { gradeOn, useHeld, usePeople } from '../people/people.slot';
import { addDays, claimDueCents, isOpen, showHundredths, useRates } from '../rates/useRates';
import { useSheetToday } from '../today/today.slot';

/** A claim's due-by: its date plus the sheet's terms in force. */
function useDueBy(sheetId: string): (claim: { date: string }) => string {
  const terms = useTermsDays(sheetId);
  return (claim) => addDays(claim.date, terms);
}

/** Whether a claim is overdue: OPEN or PENDING, and its due-by before the sheet's today. */
function useIsOverdue(sheetId: string): (claim: { status: string; date: string }) => boolean {
  const dueBy = useDueBy(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  return (claim) => today !== undefined && isOpen(claim) && dueBy(claim) < today;
}

type Overdue = { count: number; cents: bigint };

/** The overdue claims that count, per person and for the sheet: how many, and their due (late charge included) added up (n/a as 0). */
function useOverdue(sheetId: string): { byPerson: Map<number, Overdue>; sheet: Overdue } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const late = useLate(sheetId);
  const isOverdue = useIsOverdue(sheetId);
  const byPerson = new Map<number, Overdue>();
  const sheet: Overdue = { count: 0, cents: 0n };
  for (const p of people.data ?? []) {
    const mine: Overdue = { count: 0, cents: 0n };
    for (const c of claims.data ?? []) {
      if (c.personId !== p.id || !counts(c, held) || !isOverdue(c)) continue;
      mine.count += 1;
      mine.cents += claimDueCents(rates.data ?? [], gradeOn(p, c.date), c, floor, late) ?? 0n;
    }
    byPerson.set(p.id, mine);
    sheet.count += mine.count;
    sheet.cents += mine.cents;
  }
  return { byPerson, sheet };
}

function OverdueHeads() {
  return (
    <>
      <th>Overdue</th>
      <th>Overdue total</th>
    </>
  );
}

// A person's overdue count and overdue-total: their counted OPEN claims past their due-by, and those claims' due added up.
function OverdueCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const mine = useOverdue(sheetId).byPerson.get(personId) ?? { count: 0, cents: 0n };
  return (
    <>
      <td data-testid="person-overdue-count">{mine.count}</td>
      <td data-testid="person-overdue-total">{showHundredths(mine.cents)}</td>
    </>
  );
}

// A claim's due-by (its date plus the sheet's terms) and whether it is overdue (OPEN and due-by before the sheet's today).
function ClaimOverdue({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: { date: string; status: string } }) {
  const dueBy = useDueBy(sheetId);
  const isOverdue = useIsOverdue(sheetId);
  return (
    <>
      Due by <span data-testid="claim-due-by">{dueBy(claim)}</span>{' '}
      Overdue <span data-testid="claim-overdue">{isOverdue(claim) ? 'yes' : 'no'}</span>{' '}
    </>
  );
}

// The sheet's overdue count and overdue-total: everyone's added up.
function OverdueTotal({ sheetId }: { sheetId: string; user: string }) {
  const { sheet } = useOverdue(sheetId);
  return (
    <section data-testid="overdue-rollup">
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{sheet.count}</strong>{' '}
        Overdue total: <strong data-testid="rollup-overdue-total">{showHundredths(sheet.cents)}</strong>
      </p>
    </section>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 25, Component: OverdueHeads }),
  PersonCells.fill({ order: 25, Component: OverdueCells }),
  ClaimCells.fill({ order: 12, Component: ClaimOverdue }),
  SheetBody.fill({ order: 26, Component: OverdueTotal }),
];

